wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        // A transport failure is data; an out-of-allowlist request traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {} fetched {}", seconds, fetched);
        let mut notified = notifier::notify(&message);
        if !notified {
            notified = notifier::notify(&message);
        }
        // The contract requires notified == true; never emit an output that violates it.
        if !notified {
            panic!("notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
